.card {
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  padding: 0;
  scroll-margin: 6px;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--back);
  color: var(--text);
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
  transition: border-color 120ms ease;
  display: grid;
  place-items: center;
  cursor: pointer;
}
.card:hover {
  border-color: var(--text);
}
.card.revealed,
.card.matched {
  background: var(--face);
}
.card.matched {
  border-color: var(--green);
}
.card > svg {
  display: block;
  width: 100%;
  height: 100%;
}
.card-back {
  width: 12px;
  height: 12px;
  border: 2px solid var(--secondary);
  transform: rotate(45deg);
}
/* A corner mark wider than about 17% of the card would reach the top-right marker. */
.card > .matched-mark {
  position: absolute;
  right: 0;
  top: 0;
  width: 16%;
  height: 16%;
  color: var(--green);
}
.stats {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 24px;
  margin: 0 0 16px;
}
.stats div {
  min-width: 8ch;
}
dt,
dd {
  display: inline;
}
dt {
  color: var(--secondary);
  font-size: 14px;
}
dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
}
.victory {
  padding: 12px 16px;
  margin-bottom: 12px;
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 8px;
}
.celebrate {
  animation: victory-pulse 600ms ease-out 1;
}
@keyframes victory-pulse {
  50% {
    background: var(--panel);
    opacity: 0.75;
  }
}
:root {
  font-family: system-ui, sans-serif;
  font-size: 16px;
  line-height: 24px;
  color: #f4f6ff;
  background: #090b14;
  color-scheme: dark;
  --text: #f4f6ff;
  --secondary: #b8bdd2;
  --panel: #141827;
  --back: #1b2034;
  --face: #111625;
  --border: #757c9a;
  --green: #8bea7d;
  --content-max: 1120px;
  --page-padding: 16px;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
}
main {
  width: 100%;
  max-width: var(--content-max);
  margin: 0 auto;
  padding: var(--page-padding);
}
header {
  margin: 4px 0 12px;
}
h1 {
  font-size: 24px;
  line-height: 32px;
  margin: 4px 0;
}
p {
  margin: 0;
}
.eyebrow {
  color: var(--secondary);
  font-size: 14px;
}
.intro {
  font-size: 14px;
  color: var(--secondary);
  margin-bottom: 24px;
}
.help {
  color: var(--secondary);
  font-size: 14px;
  max-width: 70ch;
  margin-bottom: 12px;
}
:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 2px;
}
.game-result {
  display: flex;
  align-items: center;
  min-height: 56px;
  margin: 4px 0 8px;
}
import { expect, test } from './browser-test.ts';
import { finishBoard, loadFixedBoard } from './game-fixture.ts';

test('card transitions use 120ms and a completed game has one 600ms pulse', async ({ page }) => {
  await loadFixedBoard(page);
  const transitions = await page
    .locator('.card')
    .first()
    .evaluate((element) => {
      const style = getComputedStyle(element);
      return { duration: style.transitionDuration, property: style.transitionProperty };
    });
  expect(transitions.duration.split(',').every((duration) => parseFloat(duration) === 0.12)).toBe(
    true,
  );
  expect(transitions.property.split(',').map((value) => value.trim())).toEqual(['border-color']);
  await finishBoard(page);
  const pulse = await page.locator('.victory').evaluate((element) => {
    const style = getComputedStyle(element);
    return { duration: style.animationDuration, iterations: style.animationIterationCount };
  });
  expect(parseFloat(pulse.duration)).toBe(0.6);
  expect(Number(pulse.iterations)).toBe(1);
});

test('reduced motion removes card transitions and completion animation', async ({ page }) => {
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await loadFixedBoard(page);
  await finishBoard(page);
  expect(
    await page.locator('.victory').evaluate((element) => getComputedStyle(element).animationName),
  ).toBe('none');
  expect(
    parseFloat(
      await page
        .locator('.card')
        .first()
        .evaluate((element) => getComputedStyle(element).transitionDuration),
    ),
  ).toBe(0);
});
import { expect, test } from './browser-test.ts';
import { DealControl } from '../src/game/controls/control-labels.ts';
import {
  GAME_URL,
  exportedSnapshot,
  loadFixedBoard,
  loadTimedBoard,
  finishBoard,
} from './game-fixture.ts';

test('pauses elapsed time and a mismatch while the document is hidden', async ({ page }) => {
  await loadTimedBoard(page);
  await page.locator('.card').nth(0).click();
  await page.locator('.card').nth(1).click();
  await page.clock.runFor(200);
  // Headless Chromium leaves every tab visible, so control this browser input at the adapter.
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, get: () => true });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  const before = await exportedSnapshot(page);
  await page.clock.runFor(2000);
  expect((await exportedSnapshot(page)).elapsedMs).toBe(before.elapsedMs);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { configurable: true, get: () => false });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  await page.clock.runFor(599);
  await expect(page.locator('.card.revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await expect(page.locator('.card.closed')).toHaveCount(16);
});

